;; curriculum: MS-PreAlg (gr 6–8) — the number line; prerequisites: none
;; math target: position on a line is a number; gaps are absences; raised platforms are larger values.

app riya-level-plain "1.1.0"
"riya level 1 · The Plain — x is a number you stand on. Four beats teach the number line: flat run, pit gaps, a raised platform at y=2, then a mixed gauntlet. Catch 4 ★. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and guides carry the objective. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaPlainOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaPlainBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaPlainPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaPlainFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaPlainPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaPlainCurveSample = {
    x : number!
    y : number!
  }
  type RiyaPlainCurve = {
    label : string
    color : string
    samples : [RiyaPlainCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaPlainGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaPlainHop = {
    from : number!
    to : number!
    color : string
    label : string
  }
  type RiyaPlainFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaPlainState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaPlainBody = { x: -9, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaPlainPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaPlainFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    onPlatformY2 : boolean = false
    zoneId : string = "plain"
    platforms : [RiyaPlainPlatform] = []
    curves : [RiyaPlainCurve] = []
    guides : [RiyaPlainGuide] = []
    hops : [RiyaPlainHop] = []
  }

  entity PlainTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait PlainBody = Body.traits.PlatformerBody -> RiyaPlainState {
    events {
      STEER: PLAIN_STEER
      JUMP: PLAIN_LEAP
      PLACE: PLAIN_PLACE
      RESTART: PLAIN_RESTART
      SET_TUNING: PLAIN_TUNING
      SET_PLATFORMS: PLAIN_SET_PLATFORMS
      BODY_JUMPED: PLAIN_JUMPED
      BODY_LANDED: PLAIN_LANDED
      BODY_HAZARD: PLAIN_HAZARD
      BODY_GOAL: PLAIN_GOAL
      BODY_FELL: PLAIN_FELL
    }
    config {
      running: true
      spawn: { x: -9, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
    }
  }

  trait PlainGate = Gate.traits.ObjectiveFlow -> RiyaPlainState {
    events {
      PROGRESS: PLAIN_PROGRESS
      GAME_END: PLAIN_GAME_END
      RESTART: PLAIN_RESTART
    }
    config { running: true }
  }

  trait PlainFx = Particles.traits.FxParticles -> RiyaPlainState {
    events {
      BURST: PLAIN_BURST
    }
    config { running: true }
  }

  trait PlainPickup = Pickup.traits.Pickup -> RiyaPlainState {
    events {
      PICKED: PLAIN_PICKED
      COLLECT: PLAIN_COLLECT
      PICKUP_SET_COMPLETED: PLAIN_PICKUP_SET_COMPLETED
      SET_FEATURES: PLAIN_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait PlainLevelData -> @rebindable RiyaPlainState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "plain"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          hops: (array/map @config.hops (fn h @h))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaPlainPlatform]!
        stars : [RiyaPlainPickup]!
        curveOverlay : [RiyaPlainCurve]
        guides : [RiyaPlainGuide]
        hops : [RiyaPlainHop]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Plain"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 0"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "position on a line is a number; gaps are absence; elevation is a larger value"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 1
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaPlainPlatform] = [
        { id: "b1", x: -10, y: -2, width: 4, height: 3, type: "ground" }
        { id: "b2a", x: -4.5, y: -2, width: 1.5, height: 3, type: "ground" }
        { id: "b2b", x: -1, y: -2, width: 2, height: 3, type: "ground" }
        { id: "b2c", x: 3, y: -2, width: 1.5, height: 3, type: "ground" }
        { id: "b3", x: 5.5, y: 2, width: 2.5, height: 0.4, type: "platform" }
        { id: "b4a", x: 6.5, y: -2, width: 1.2, height: 3, type: "ground" }
        { id: "b4b", x: 8.5, y: 2, width: 1.2, height: 0.4, type: "platform" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Four beats: flat run, pit gaps, raised platform y=2, mixed gauntlet."
        @tier "domain"
      stars : [RiyaPlainPickup] = [
        { id: "s1", x: -8, y: 1.5, kind: "star", glyph: "★", message: "" }
        { id: "s2", x: -2, y: 1.5, kind: "star", glyph: "★", message: "" }
        { id: "s3", x: 6.75, y: 3.2, kind: "star", glyph: "★", message: "" }
        { id: "s4", x: 9.1, y: 3.2, kind: "star", glyph: "★", message: "" }
        { id: "scale", x: 0, y: 3.5, kind: "scale", glyph: "×2", message: "2x" }
      ]
        @label "Stars"
        @description "Canonical collectibles — seeds the pickup authority via RIYA_LEVEL_DATA."
        @tier "domain"
      curveOverlay : [RiyaPlainCurve] = [ { label: "y = 0", color: "#38bdf8", samples: [ { x: -10, y: 0 }, { x: 9.4, y: 0 } ], dash: "dashed" } ]
        @label "Curve Overlay"
        @description "The number-line axis drawn faintly behind the terrain bars."
        @tier "presentation"
      guides : [RiyaPlainGuide] = [
        { kind: "hline", at: 0, color: "#94a3b8", dash: "dashed", label: "" }
        { kind: "vline", at: -6, color: "#94a3b8", dash: "dotted", label: "" }
        { kind: "vline", at: 0, color: "#a78bfa", dash: "dashed", label: "x = 0" }
        { kind: "vline", at: 5.5, color: "#34d399", dash: "dotted", label: "" }
      ]
        @label "Guides"
        @description "Reference lines: the x-axis, beat boundaries, and the origin."
        @tier "presentation"
      hops : [RiyaPlainHop] = [
        { from: -3, to: -1, color: "#7c3aed", label: "" }
        { from: 1, to: 3, color: "#7c3aed", label: "" }
      ]
        @label "Hops"
        @description "Number-line jump arcs across the pit gaps."
        @tier "presentation"
    }
  }

  trait PlainTutorialPreview -> PlainTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait PlainTutorial = Tutorial.traits.TutorialOverlay -> PlainTutorialData {
    events {
      SHOW: PLAIN_TUTORIAL_SHOW
      TUTORIAL_DONE: PLAIN_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.PlainTutorialPreview
      steps: [
        { id: "intro", title: "The Plain", body: "Every spot on the ground is a number. Run right to make x bigger; gaps are missing numbers; the raised ledge is a larger value." }
      ]
    }
  }

  trait RiyaPlainGenre = Genre.traits.PlatformerPuzzle -> RiyaPlainState {
    config {
      agencyTrait: @trait.PlainBody
      challengeTrait: @trait.PlainBody
      goalTrait: @trait.PlainGate
      rewardTrait: @trait.PlainPickup
      feedbackTrait: @trait.PlainFx
    }
  }

  trait RiyaPlainPlay -> @rebindable RiyaPlainState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit PLAIN_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "PLAIN_LEFT", KeyA: "PLAIN_LEFT", ArrowRight: "PLAIN_RIGHT", KeyD: "PLAIN_RIGHT", ArrowUp: "PLAIN_JUMP", KeyW: "PLAIN_JUMP", Space: "PLAIN_JUMP" }
            keyUpMap: { ArrowLeft: "PLAIN_STOP", KeyA: "PLAIN_STOP", ArrowRight: "PLAIN_STOP", KeyD: "PLAIN_STOP" }
            curves: @entity.curves
            guides: @entity.guides
            hops: @entity.hops
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "scale") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "PLAIN_LEFT", right: "PLAIN_RIGHT", up: "PLAIN_JUMP" }, directionReleaseEvents: { left: "PLAIN_STOP", right: "PLAIN_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "plain")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.hops @payload.hops)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit PLAIN_SET_PLATFORMS { platforms: @payload.platforms })
        (emit PLAIN_SET_FEATURES { features: @payload.stars })

      PLAIN_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit PLAIN_STEER { dir: -1 })

      PLAIN_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit PLAIN_STEER { dir: 1 })

      PLAIN_STOP -> idle when (== @entity.active true)
        (emit PLAIN_STEER { dir: 0 })

      PLAIN_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit PLAIN_LEAP {})

      PLAIN_FELL -> idle when (== @entity.active true)
        (emit PLAIN_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit PLAIN_BURST { particles: (array/map [ "fx-plain-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#f87171", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })

      PLAIN_PICKED -> idle when (== @entity.active true)
        (emit PLAIN_BURST { particles: (array/map [ "fx-plain-pickup" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (object/get @payload glyph), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "sparkle", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
      PLAIN_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit PLAIN_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      PLAIN_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit PLAIN_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "the number line is home", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
        (emit PLAIN_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      PLAIN_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "plain" })

      PLAIN_TUTORIAL_DONE -> idle
        (emit PLAIN_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: -5, z: 8, y: 0, message: "x is a number you stand on", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "PLAIN_LEFT", KeyA: "PLAIN_LEFT", ArrowRight: "PLAIN_RIGHT", KeyD: "PLAIN_RIGHT", ArrowUp: "PLAIN_JUMP", KeyW: "PLAIN_JUMP", Space: "PLAIN_JUMP" }
            keyUpMap: { ArrowLeft: "PLAIN_STOP", KeyA: "PLAIN_STOP", ArrowRight: "PLAIN_STOP", KeyD: "PLAIN_STOP" }
            curves: @entity.curves
            guides: @entity.guides
            hops: @entity.hops
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "scale") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      PLAIN_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      PLAIN_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      PLAIN_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      PLAIN_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (PLAIN_LEAP), which accepts it only while grounded."
        @tier "domain"
      PLAIN_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      PLAIN_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      PLAIN_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      PLAIN_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      PLAIN_JUMPED -> external {
        id : string
      }
        @description "Jump take-off signal from this world's platformer-body authority (renamed BODY_JUMPED)."
        @tier "domain"
      PLAIN_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the star glyph, the challenge trait applies kind-conditional effects."
        @tier "domain"
      PLAIN_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      PLAIN_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      PLAIN_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      PLAIN_BURST -> external {
        particles : [RiyaPlainFx]
      }
        @description "Particle batch spawned on star pickup, pit respawn, or narrative beat; fx-particles fades it."
        @tier "domain"
      PLAIN_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted when a pickup is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      PLAIN_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      PLAIN_SET_PLATFORMS -> external {
        platforms : [RiyaPlainPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      PLAIN_SET_FEATURES -> external {
        features : [RiyaPlainPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      PLAIN_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaPlainPlatform]!
        stars : [RiyaPlainPickup]!
        curveOverlay : [RiyaPlainCurve]
        guides : [RiyaPlainGuide]
        hops : [RiyaPlainHop]
      }
    }

    config {
      respawnX : number = -9
        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches PlainBody spawn.x)."
        @tier "domain"
      respawnY : number = 1
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches PlainBody spawn.y)."
        @tier "domain"
      objectiveText : string = ""
        @label "Objective Text"
        @description "Metadata only — the geometry and FX carry the objective."
        @tier "presentation"
      worldName : string = "The Plain"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      conceptText : string = "position on a line is a number; gaps are absence; elevation is a larger value"
        @label "Concept Text"
        @description "The world's one math idea — metadata for the picker/factory, not rendered in-game."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      terrainColor : string = "#78716c"
        @label "Terrain Color"
        @description "Bar color for the ground/platform bars."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of telemetry readout and floating labels."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (debug aid only). Off by default; teaching text is FX-based."
        @tier "domain"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow, kept short so it does not dip behind the sprite."
        @tier "presentation"
      fxPresets : [RiyaPlainFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      xMin : number = -10
        @label "X Min"
        @description "Left edge of the visible math window."
        @tier "presentation"
      xMax : number = 10
        @label "X Max"
        @description "Right edge of the visible math window."
        @tier "presentation"
      yMin : number = -2
        @label "Y Min"
        @description "Bottom edge of the visible math window."
        @tier "presentation"
      yMax : number = 12
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait PlainChallenge -> @rebindable RiyaPlainState [game-core, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.onPlatformY2 false)

      PLAIN_LANDED -> idle when (and (== @entity.zoneId @config.zoneId) (and (== @entity.active true) (> @entity.body.y 1.5) (== @entity.onPlatformY2 false)))
        (set @entity.onPlatformY2 true)
        (emit PLAIN_BURST { particles: (array/map [ "landed" ] (fn _ { id: "narrative-platform", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 1.8), y: 0, message: "a gap is a missing number", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })

      PLAIN_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (== @payload.kind "scale")
          (do
            (emit PLAIN_TUNING { moveSpeed: 10, jumpStrength: 13 })
            (emit PLAIN_BURST { particles: (array/concat
              { id: "narrative-scale-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "2x", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
              { id: "narrative-scale-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.5), y: 0, message: "number line stretches", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
            ) }))
          null)
    }

    emits {
      PLAIN_TUNING -> external {
        moveSpeed : number
        jumpStrength : number
      }
        @description "Renamed SET_TUNING consumed by this world's platformer-body authority; applied when the ×2 speed boost pad is collected."
        @tier "domain"
      PLAIN_BURST -> external {
        particles : [RiyaPlainFx]
      }
        @description "Particle batch spawned on star pickup or the raised-platform narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      PLAIN_LANDED { id : string }
      PLAIN_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "plain"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaPlainClear -> @rebindable RiyaPlainState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "PLAIN_NEXT", variant: "primary" } ]
        })

      PLAIN_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      PLAIN_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-plain"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Plain clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Every point on the line is a number."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-plain" as RiyaPlainPage -> PlainLevelData, PlainBody, PlainGate, PlainFx, PlainPickup, PlainTutorial, RiyaPlainGenre, RiyaPlainPlay, PlainChallenge, RiyaPlainClear
}
